/**
 * Type guard to check if the given value is an array where all elements are strings.
 * @param x The value to check.
 * @returns True if x is a string[], false otherwise.
 */
function isStringArray(x: unknown): x is string[] {
  // 1. Check if x is an array
  if (!Array.isArray(x)) {
    return false;
  }

  // 2. Check if every element in the array is a string
  // We use .every() for efficient checking.
  return x.every(item => typeof item === 'string');
}

// --- Examples ---

// 1. Valid case
const validArray: string[] = ["apple", "banana", "cherry"];
if (isStringArray(validArray)) {
  // Inside this block, TypeScript knows validArray is string[]
  console.log("Valid Array:", validArray.join(', ')); // Output: apple, banana, cherry
}

// 2. Invalid case (contains a number)
const mixedArray: (string | number)[] = ["hello", 123, "world"];
if (!isStringArray(mixedArray)) {
  console.log("Mixed Array is not a string array."); // Output: Mixed Array is not a string array.
